insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-cb-118', 'chemistry-chemical-bonding-and-molecular-structure', 'chemistry', 'In a common canonical form of ozone, the central oxygen atom carries a formal charge of', '["0","+1","−2","+2"]'::jsonb, 1, 'Central O has six valence electrons, one lone pair and three bonds, so FC = 6 − 2 − 3 = +1.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
