insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-cb-119', 'chemistry-chemical-bonding-and-molecular-structure', 'chemistry', 'Resonance in the carbonate ion means that', '["the carbon atom physically jumps among the three oxygens","the real ion is a hybrid of three equivalent Lewis forms","only one C=O double bond exists as a fixed localisation","the ion is paramagnetic with an unpaired electron"]'::jsonb, 1, 'The three C-O bonds are identical; the pi electron pair is delocalised over the whole ion.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
