insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-cb-124', 'chemistry-chemical-bonding-and-molecular-structure', 'chemistry', 'A satisfactory Lewis picture of carbon monoxide places', '["a C≡O triple bond with formal charges −1 on carbon and +1 on oxygen","only a C-O single bond and no lone pairs","a complete octet on carbon with no lone pair on carbon","an ionic pair C4+ O4-"]'::jsonb, 0, ':C≡O: gives carbon an octet. Formal charges are −1 (C) and +1 (O), which matches the small dipole with carbon at the negative end.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
